mod common;

use std::fs;
use std::path::Path;
use std::process::Command;

use common::{work_dir, write, yashy};

fn lock_text(name: &str, version: &str, source: &str, hash: &str) -> String {
    format!(
        "# This file is generated by `yashy lock`; do not edit it by hand.\n\
         version = 1\n\n[[package]]\nname = \"{name}\"\nversion = \"{version}\"\n\
         source = \"{source}\"\nhash = \"sha256:{hash}\"\ndependencies = []\n"
    )
}

fn run_lock_check(directory: &Path) -> std::process::Output {
    Command::new(yashy())
        .arg("lock")
        .arg("--check")
        .arg(directory)
        .output()
        .expect("the yashy CLI must be runnable")
}

#[test]
fn lock_check_accepts_a_matching_pair() {
    let dir = work_dir("lock-check-ok");
    write(
        &dir,
        "yashy.toml",
        "[package]\nname = \"app\"\nversion = \"0.1.0\"\n\n[dependencies.net]\npath = \"net\"\n",
    );
    write(&dir, "net/src/net.ya", "pub fn open() -> int { 1 }\n");
    let hash = yashy_manifest::hash_tree(&dir.join("net")).expect("hash the dependency");
    write(
        &dir,
        "yashy.lock",
        &lock_text(
            "net",
            "0.1.0",
            "path+net",
            hash.trim_start_matches("sha256:"),
        ),
    );

    let output = run_lock_check(&dir);
    assert!(
        output.status.success(),
        "a matching lock must pass:\n{}",
        String::from_utf8_lossy(&output.stderr)
    );
    assert!(
        String::from_utf8_lossy(&output.stdout).contains("up to date"),
        "{}",
        String::from_utf8_lossy(&output.stdout)
    );
}

#[test]
fn lock_check_names_both_versions_when_the_manifest_changed() {
    let dir = work_dir("lock-check-stale");
    write(
        &dir,
        "yashy.toml",
        "[package]\nname = \"app\"\nversion = \"0.1.0\"\n\n[dependencies]\nhttp = \"0.3.2\"\n",
    );
    write(
        &dir,
        "yashy.lock",
        &lock_text(
            "http",
            "0.3.1",
            "registry+file:///registry",
            &"a".repeat(64),
        ),
    );

    let output = run_lock_check(&dir);
    assert_eq!(output.status.code(), Some(1));
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(stderr.contains("E1802"), "{stderr}");
    assert!(stderr.contains("0.3.1"), "{stderr}");
    assert!(stderr.contains("0.3.2"), "{stderr}");
    assert!(stderr.contains("yashy update"), "{stderr}");
    assert!(stderr.contains("docs:"), "{stderr}");
}

#[test]
fn lock_check_without_a_lock_says_update() {
    let dir = work_dir("lock-check-missing");
    write(
        &dir,
        "yashy.toml",
        "[package]\nname = \"app\"\nversion = \"0.1.0\"\n",
    );
    let output = run_lock_check(&dir);
    assert_eq!(output.status.code(), Some(1));
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(stderr.contains("E1802"), "{stderr}");
    assert!(stderr.contains("yashy update"), "{stderr}");
}

#[test]
fn a_build_refuses_a_stale_lock_before_compiling() {
    let dir = work_dir("lock-build-stale");
    write(&dir, "main.ya", "fn main() { }\n");
    write(
        &dir,
        "yashy.toml",
        "[package]\nname = \"app\"\nversion = \"0.1.0\"\n\n[dependencies]\nhttp = \"0.3.2\"\n",
    );
    write(
        &dir,
        "yashy.lock",
        &lock_text(
            "http",
            "0.3.1",
            "registry+file:///registry",
            &"a".repeat(64),
        ),
    );

    let output = Command::new(yashy())
        .arg("build")
        .arg(dir.join("main.ya"))
        .current_dir(&dir)
        .output()
        .expect("the yashy CLI must be runnable");
    assert_eq!(output.status.code(), Some(1));
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(stderr.contains("E1802"), "{stderr}");
    // It stopped at the lock, not at a parse or type error.
    assert!(!stderr.contains("error[E0"), "{stderr}");
    let _ = fs::remove_file(dir.join("main"));
}
